#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    int maxCoins(std::vector<int>& piles) {
        std::sort(piles.begin(), piles.end());
        int n = piles.size(), ans = 0;
        for (int i = n / 3; i < n; i += 2) {
            ans += piles[i];
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxCoins(int[] piles) {
        Arrays.sort(piles);
        int n = piles.length, ans = 0;
        for (int i = n / 3; i < n; i += 2) {
            ans += piles[i];
        }
        return ans;
    }
}

var maxCoins = function(piles) {
    piles.sort((a, b) => a - b);
    const n = piles.length;
    let ans = 0;
    for (let i = Math.floor(n / 3); i < n; i += 2) {
        ans += piles[i];
    }
    return ans;
};
